"""Generate run.sh: the whole PDF -> snapshot pipeline for one project directory."""

from __future__ import annotations

from pathlib import Path
import shlex

import click

_TEMPLATE = r"""#!/usr/bin/env bash
# Generated by `deepresearch-flow utils init-run`. This file is meant to be edited.
#
#   ./run.sh                      everything: ocr chain, then 3 chains in parallel (tmux), then build
#   ./run.sh STEP[,STEP...]       only these steps, in the order given, one after another.
#                                 Always runs them, even if logs/STEP.done exists.
#   ./run.sh list                 print all step names
#
# Each step is a function s_<name> below, one command per line. Change a parameter by
# editing that line. Skip a command by commenting it out.
# A step that fails stops its chain (set -e). Exit code 3 means "some items failed":
#   retry  runs the command again with --retry-failed, up to ROUNDS times
#   rerun  runs the very same command again (it skips finished files)
#   once   only warns
# In a full run, finished steps (logs/STEP.done) are skipped, so a rerun resumes at the
# failed step. To redo one, delete its .done file or name it on the command line.

# ---- settings ---------------------------------------------------------------
NAME=@@NAME@@
MODEL=@@MODEL@@
LANG_TO=@@LANG@@
CONFIG=@@CONFIG@@
OCR_CONFIG=@@OCR_CONFIG@@
ROUNDS=@@ROUNDS@@
NOTIFY_URL=${NOTIFY_URL:-}      # optional, https://host/api/<uuid>/get
REPO=@@REPO@@
drflow() { uv run --project "$REPO" deepresearch-flow "$@"; }

# Order matters inside a chain. The chains in PARALLEL run side by side in tmux.
CHAIN_ocr="ocr fix fix-math organize"
CHAIN_simple="simple fix-simple fix-math-simple"
CHAIN_deep_read="deep_read fix-deep_read fix-math-deep_read fix-mermaid-deep_read"
CHAIN_translate="translate fix-translated fix-math-translated"
PARALLEL="simple deep_read translate"
ALL="$CHAIN_ocr $CHAIN_simple $CHAIN_deep_read $CHAIN_translate build"

# ---- helpers (usually no need to edit) --------------------------------------
cd "$(dirname "$0")" || exit 1
ROOT=$(pwd)
PARTIAL=3
FORCE=""
export PATH="$REPO/node_modules/.bin:$PATH"   # fix-mermaid needs mmdc
mkdir -p logs logs/simple logs/deep_read      # extract writes ./paper_stage_outputs in its cwd

notify() {
  [ -n "$NOTIFY_URL" ] || return 0
  curl -fsS --max-time 10 -G "$NOTIFY_URL" \
    --data-urlencode "format=text" --data-urlencode "msg=$NAME: $1" >/dev/null 2>&1 || true
}

once() {
  local rc=0
  "$@" || rc=$?
  if [ $rc -eq $PARTIAL ]; then echo "WARNING: some items failed: $*"; return 0; fi
  return $rc
}
retry() { _again " --retry-failed" "$@"; }
rerun() { _again "" "$@"; }
_again() {
  local extra=$1; shift
  local rc=0 n=0
  "$@" || rc=$?
  while [ $rc -eq $PARTIAL ] && [ $n -lt "$ROUNDS" ]; do
    n=$((n+1)); echo "retry round $n: $*$extra"
    rc=0; "$@" $extra || rc=$?
  done
  if [ $rc -eq $PARTIAL ]; then echo "WARNING: still failed items after $ROUNDS rounds: $*"; return 0; fi
  return $rc
}

# ---- steps: one command per line --------------------------------------------
s_ocr() {
  rerun drflow recognize ocr pdf --config "$OCR_CONFIG" --output-dir ocr
}
s_fix() {
  once drflow recognize fix --input ocr -r --in-place
}
s_fix-math() {
  retry drflow recognize fix-math --input ocr -r --in-place \
    --config "$CONFIG" --model "$MODEL" --report logs/fix-math-ocr.json
}
s_organize() {
  once drflow recognize organize --input ocr -r \
    --output-simple md_simple --output-base64 md_base64
}

s_simple() {
  (cd logs/simple && retry drflow paper extract \
    --input "$ROOT/md_simple" --config "$CONFIG" --model "$MODEL" --prompt-template simple \
    --output "$ROOT/simple.json" --errors "$ROOT/logs/simple-errors.json")
}
s_fix-simple() {
  once drflow recognize fix --input simple.json --json --in-place
}
s_fix-math-simple() {
  retry drflow recognize fix-math --input simple.json --json --in-place \
    --config "$CONFIG" --model "$MODEL" --report logs/fix-math-simple.json
}

s_deep_read() {
  (cd logs/deep_read && retry drflow paper extract \
    --input "$ROOT/md_simple" --config "$CONFIG" --model "$MODEL" --prompt-template deep_read \
    --output "$ROOT/deep_read.json" --errors "$ROOT/logs/deep_read-errors.json")
}
s_fix-deep_read() {
  once drflow recognize fix --input deep_read.json --json --in-place
}
s_fix-math-deep_read() {
  retry drflow recognize fix-math --input deep_read.json --json --in-place \
    --config "$CONFIG" --model "$MODEL" --report logs/fix-math-deep_read.json
}
s_fix-mermaid-deep_read() {
  retry drflow recognize fix-mermaid --input deep_read.json --json --in-place \
    --config "$CONFIG" --model "$MODEL" --report logs/fix-mermaid-deep_read.json
}

s_translate() {
  rerun drflow translator translate --input md_base64 --config "$CONFIG" --model "$MODEL" \
    --target-lang "$LANG_TO" --fix-level moderate \
    --output-dir md_base64_translated --debug-dir logs/translator
}
s_fix-translated() {
  once drflow recognize fix --input md_base64_translated -r --in-place
}
s_fix-math-translated() {
  retry drflow recognize fix-math --input md_base64_translated -r --in-place \
    --config "$CONFIG" --model "$MODEL" --report logs/fix-math-translated.json
}

s_build() {
  mkdir -p dist
  local prev=()
  [ -f "dist/$NAME.db" ] && prev=(--previous-snapshot-db "dist/$NAME.db")   # keeps paper_id stable
  drflow paper db snapshot build \
    -i simple.json -i deep_read.json -b @@BIB@@ \
    --md-root md_simple --md-translated-root md_base64_translated --pdf-root pdf \
    --output-db "dist/$NAME.db" --static-export-dir "dist/$NAME-export" "${prev[@]}"
}

# ---- driver (usually no need to edit) ---------------------------------------
# run_step NAME: run s_NAME, leave logs/NAME.done or logs/NAME.failed, log to logs/NAME.log
run_step() {
  local name=$1
  if [ -z "$FORCE" ] && [ -e "logs/$name.done" ]; then echo "[$name] already done"; return 0; fi
  rm -f "logs/$name.done" "logs/$name.failed"
  echo "[$name] start"
  ( set -e; "s_$name" ) 2>&1 | tee -a "logs/$name.log"
  if [ "${PIPESTATUS[0]}" -eq 0 ]; then touch "logs/$name.done"; else touch "logs/$name.failed"; return 1; fi
}

# run_seq LABEL STEP...: run steps one after another, stop at the first failure
run_seq() {
  local label=$1; shift
  local t0=$SECONDS s
  for s in "$@"; do
    run_step "$s" || { notify "$label FAILED at $s, see logs/$s.log"; return 1; }
  done
  notify "$label done ($(( (SECONDS-t0)/60 )) min)"
}

# Entry point used inside the tmux windows.
if [ "${1:-}" = --chain ]; then v="CHAIN_$2"; run_seq "$2" ${!v}; exit $?; fi

if [ $# -gt 0 ]; then
  case $1 in -h|--help|list) echo "steps: $ALL"; exit 0 ;; esac
  IFS=', ' read -ra SEL <<< "$*"
  for s in "${SEL[@]}"; do
    case " $ALL " in *" $s "*) ;; *) echo "unknown step: $s"; echo "steps: $ALL"; exit 1 ;; esac
  done
  FORCE=1
  run_seq "steps ${SEL[*]}" "${SEL[@]}"; exit $?
fi

run_seq ocr $CHAIN_ocr || exit 1

command -v tmux >/dev/null || { echo "tmux is required"; exit 1; }
# A dedicated tmux server inherits this shell's environment (API keys, NOTIFY_URL).
T="tmux -L drflow-$NAME"; S=run
# kill-session, not kill-server: a new session started right after kill-server can vanish.
$T kill-session -t "$S" 2>/dev/null
$T new-session -d -s "$S" -n main "sleep 86400" >/dev/null 2>&1 </dev/null
parallel_steps=""
for c in $PARALLEL; do
  v="CHAIN_$c"; parallel_steps="$parallel_steps ${!v}"
  for s in ${!v}; do rm -f "logs/$s.failed"; done
  $T new-window -d -t "$S:" -n "$c" "./run.sh --chain $c; echo; echo '[$c] finished, press Enter'; read"
done
echo "$T attach -t $S   (windows: $PARALLEL)"
while :; do
  pending=0; failed=0
  for s in $parallel_steps; do
    [ -e "logs/$s.failed" ] && failed=1
    [ -e "logs/$s.done" ] || pending=1
  done
  [ $failed -eq 1 ] && { echo "a step failed (see logs/*.failed); fix it and run ./run.sh again"; $T kill-window -t "$S:main" 2>/dev/null; exit 1; }
  [ $pending -eq 0 ] && break
  sleep 10
done
$T kill-window -t "$S:main" 2>/dev/null

run_seq build build
"""


def _find_bib(project: Path) -> Path:
    bibs = sorted(project.glob("*.bib"))
    if len(bibs) != 1:
        raise click.ClickException(
            f"{project} must contain exactly one .bib file, found {len(bibs)}"
        )
    return bibs[0]


@click.command("init-run")
@click.argument("project", type=click.Path(exists=True, file_okay=False, path_type=Path))
@click.option("-m", "--model", required=True, help="provider/model used by every LLM step")
@click.option("--target-lang", default="zh", show_default=True)
@click.option("--config", "config_name", default="config.toml", show_default=True,
              help="LLM config; resolved against the current directory and stored as an absolute path")
@click.option("--ocr-config", "ocr_config_name", default="ocr.toml", show_default=True,
              help="OCR config; resolved like --config")
@click.option("--rounds", default=3, show_default=True, help="Retry rounds per step")
def init_run(
    project: Path,
    model: str,
    target_lang: str,
    config_name: str,
    ocr_config_name: str,
    rounds: int,
) -> None:
    """Write PROJECT/run.sh. PROJECT needs pdf/ and exactly one .bib."""
    project = project.resolve()
    if not (project / "pdf").is_dir():
        raise click.ClickException(f"{project}/pdf not found")
    bib = _find_bib(project)
    repo = Path(__file__).resolve().parents[3]
    script = _TEMPLATE
    for key, value in {
        "NAME": project.name,
        "MODEL": model,
        "LANG": target_lang,
        "CONFIG": str(Path(config_name).resolve()),
        "OCR_CONFIG": str(Path(ocr_config_name).resolve()),
        "ROUNDS": str(rounds),
        "REPO": str(repo),
        "BIB": bib.name,
    }.items():
        script = script.replace(f"@@{key}@@", shlex.quote(value))
    target = project / "run.sh"
    target.write_text(script, encoding="utf-8")
    target.chmod(0o755)
    click.echo(f"wrote {target}")
